#!/usr/bin/env python3
# luxarch:no-gate-bypass hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny commands that bypass the gate (skipping or redirecting git hooks, deselecting failures).

The fleet has ONE gate: `make check`, plus the committed git hooks. `git commit --no-verify`
skips the secret scan; a pytest run that leaves tests out (`--deselect`, `--ignore`,
`--ignore-glob`, a `-k`/`-m` expression that is only a negation), wherever pytest runs (`uv run
pytest`, `python -m pytest`, inside `docker compose run`) or through `PYTEST_ARGS`/
`PYTEST_ADDOPTS`, turns a red suite green without fixing anything. Both are 'route around the
guard', which the conduct standard bans outright. A `-k`/`-m` selection (`login`, `login and not
slow`) is a targeted run and passes; leaving a test out by naming the others cannot be told apart
from one, and is not seen.

git is read as argv (`_cmdtext.git_calls`), because git accepts the same bypass in many spellings:
  * `--no-verify` or any prefix git accepts for it (`--no-veri`) on a subcommand that has it,
    wherever global options such as `-C <dir>` put the subcommand; `-n` on `git commit`, alone or
    combined (`-nm msg`)
  * hooks redirected away from the committed ones, for one run (`-c core.hooksPath=…`,
    `--config-env`, `GIT_CONFIG_KEY_<n>`/`GIT_CONFIG_PARAMETERS`, also `export`ed by an earlier
    command) or for good (`git config core.hooksPath …`, `--unset`); `include.path` and
    `includeIf.*.path` likewise. Setting it to the committed `hooks` is the fleet's own install, and
    reading it (`git config core.hooksPath`) passes
  * `SKIP=` on a commit or push
  * a force push: `--force`, `-f`, `--mirror`, a `+refspec`, or the same through one-run
    `remote.<name>.push` / `remote.<name>.mirror` config (`--force-with-lease` passes)
  * any of these inside a one-run alias (`-c alias.ci='commit --no-verify' ci`)

A command the shell runs from inside another (`bash -c`, `eval`, `$(…)`, backticks) is judged the
same way. Not seen: an alias or a hooks path already stored in `.git/config`, a `.git/config`
edited directly, and text piped into a shell (`… | sh`).

PreToolUse(Bash): deny the bypass. A tool call this hook cannot read or judge is denied too.
"""

from __future__ import annotations

import os
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (  # sibling helper, loaded by path
    GIT_NO_VERIFY_SUBS,
    GitCall,
    SimpleCommand,
    command_text,
    executable_texts,
    force_push,
    git_calls,
    guarded,
    is_abbrev,
    is_hook_redirect,
    load_event,
    shell_split,
    simple_commands,
    text_field,
    tool_input,
)

BYPASS = (
    (
        re.compile(r"\bgit\s+(?:commit|push)\b[^\n]{0,400}?--no-verify"),
        "--no-verify skips the committed git hooks (incl. the secret scan)",
    ),
    (re.compile(r"\bSKIP=\S+\s+git\s+commit"), "SKIP= disables hooks for this commit"),
    (
        re.compile(r"\bpytest\b[^\n]{0,400}?--deselect\b"),
        "--deselect drops a failing test instead of fixing it",
    ),
    (
        re.compile(r"\bgit\s+push\b[^\n]{0,400}?--force(?!-with-lease)\b"),
        "--force can destroy pushed history (use --force-with-lease, and say why)",
    ),
)

_CONFIG_READS = {"--get", "--get-all", "--get-regexp", "--get-urlmatch", "-l", "--list"}
_CONFIG_READ_SUBS = {"get", "list"}
_CONFIG_REMOVES = {"--unset", "--unset-all", "--remove-section", "--rename-section"}
_CONFIG_REMOVE_SUBS = {"unset", "remove-section", "rename-section"}


def _config_write_redirects(g: GitCall) -> bool:
    """`git config` that sets, unsets or renames a hook-redirect key."""
    if g.sub != "config":
        return False
    words = list(g.positionals)
    if (
        any(f in _CONFIG_READS for f in g.flags)
        or words[:1]
        and words[0] in _CONFIG_READ_SUBS
    ):
        return False
    removes = any(f in _CONFIG_REMOVES for f in g.flags) or (
        bool(words) and words[0] in _CONFIG_REMOVE_SUBS
    )
    for i, w in enumerate(words):
        key = w.lower()
        if i + 1 >= len(words) and not removes:
            continue  # `git config core.hooksPath`: a key with no value is a read
        if (
            key == "core.hookspath"
            or key == "include.path"
            or key.startswith("includeif.")
        ):
            value = None if removes or i + 1 >= len(words) else words[i + 1]
            if is_hook_redirect(key, value):
                return True
    return False


def _git_bypass(g: GitCall) -> str | None:
    if g.sub in GIT_NO_VERIFY_SUBS and any(
        is_abbrev(f, "--no-verify", 9) for f in g.flags
    ):
        return "--no-verify skips the committed git hooks (incl. the secret scan)"
    if g.sub == "commit" and "-n" in g.flags:
        return "`git commit -n` is --no-verify: it skips the committed git hooks"
    if any(is_hook_redirect(k, v) for k, v in g.config):
        return "redirecting core.hooksPath / include.path for one run skips the committed hooks"
    if _config_write_redirects(g):
        return "pointing core.hooksPath (or an include) away from the committed hooks disables them"
    if g.sub in ("commit", "push") and any(name == "SKIP" for name, _ in g.env):
        return "SKIP= disables hooks for this commit"
    if force_push(g):
        return "a force push (--force, -f, --mirror or a +refspec) can destroy pushed history (use --force-with-lease, and say why)"
    return None


_PYTEST_DROPS = ("--deselect", "--ignore", "--ignore-glob")


def _pytest_drops(args: list[str]) -> str | None:
    """A pytest argument list that leaves tests out of the run.

    `-k`/`-m` select what runs, and a selection is a targeted run; an expression that is only a
    negation (`not test_x`) exists to leave tests out. A selection that leaves a failing test out by
    naming the others cannot be told from a targeted run, and passes."""
    for i, w in enumerate(args):
        if w.split("=", 1)[0] in _PYTEST_DROPS:
            return f"`{w.split('=', 1)[0]}` drops tests from the run instead of fixing them"
        for opt in ("-k", "-m"):
            expr = w[2:] if w.startswith(opt) and len(w) > 2 else None
            if w == opt and i + 1 < len(args):
                expr = args[i + 1]
            if (
                expr is not None
                and re.match(r"\s*\(?\s*not\b", expr)
                and not re.search(r"\b(?:and|or)\b", expr)
            ):
                return f"`{opt} 'not …'` deselects tests instead of fixing them"
    return None


def _pytest_args(argv: list[str]) -> list[str] | None:
    """The arguments pytest gets, wherever in the command it runs (`uv run pytest`, `docker
    compose run app pytest`, `python -X dev -m pytest`, `python3 -mpytest`), or None."""
    for i, w in enumerate(argv):
        if os.path.basename(w) in ("pytest", "py.test"):
            return argv[i + 1 :]
        if os.path.basename(w).startswith("python"):
            for j in range(i + 1, len(argv)):
                if argv[j] == "-m" and argv[j + 1 : j + 2] == ["pytest"]:
                    return argv[j + 2 :]
                if argv[j] == "-mpytest":
                    return argv[j + 1 :]
                if not argv[j].startswith("-"):
                    break
    return None


def _pytest_bypass(sc: SimpleCommand) -> str | None:
    """pytest run (directly or through a runner) or PYTEST_ARGS/PYTEST_ADDOPTS that drops tests."""
    argv = list(sc.argv)
    args = _pytest_args(argv)
    if args is not None:
        why = _pytest_drops(args)
        if why:
            return why
    passed = [v for k, v in sc.env if k in ("PYTEST_ARGS", "PYTEST_ADDOPTS")]
    passed += [
        w.split("=", 1)[1]
        for w in argv
        if w.startswith(("PYTEST_ARGS=", "PYTEST_ADDOPTS="))
    ]
    for value in passed:
        try:
            words = shell_split(value)
        except ValueError:
            words = value.split()
        why = _pytest_drops(words)
        if why:
            return why
    return None


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    raw = text_field(tool_input(ev), "command")
    texts = [command_text(t) for t in executable_texts(raw)]
    why = next((w for cmd in texts for rx, w in BYPASS if rx.search(cmd)), None)
    if why is None:
        why = next((w for w in map(_git_bypass, git_calls(raw)) if w), None)
    if why is None:
        why = next((w for w in map(_pytest_bypass, simple_commands(raw)) if w), None)
    if why is None:
        return 0
    print(
        f"DENIED: {why}.\n"
        "The fleet gate is `make check` + the committed hooks — a red is fixed or "
        "escalated, never routed around. If this is genuinely necessary, ask the owner.",
        file=sys.stderr,
    )
    return 2


sys.exit(guarded(main, "no-gate-bypass"))
